--
-- Name: cultural_objects_sync_geometry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cultural_objects_sync_geometry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.geometry := ST_SetSRID(ST_MakePoint(NEW.longitude, NEW.latitude), 4326);
    NEW.geog := NEW.geometry::geography;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;


